import{_ as r,a as e,c as t,ac as s}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"小学四年级数学：独立习题集 · 小数与单位换算至植树间隔与周期规律","description":"20 个知识点、40 道小学四年级练习，每题提供默认折叠的答案、步骤和易错说明。","frontmatter":{"title":"小学四年级数学：独立习题集 · 小数与单位换算至植树间隔与周期规律","description":"20 个知识点、40 道小学四年级练习，每题提供默认折叠的答案、步骤和易错说明。","splitFrom":"life/math/primary/grade-4/exercises.md","showdocs":{"topics":[{"id":"math","title":"数学","link":"/topics/math/"}],"kind":"习题与解析","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"小学四年级数学：独立习题集","summary":"20 个知识点、40 道小学四年级练习，每题提供默认折叠的答案、步骤和易错说明。","status":"active","related":[{"title":"八年级数学公式速查","link":"/life/math/junior/grade-8/formulas","kind":"公式与参考","scope":"general","audience":"general"},{"title":"八年级数学知识讲解","link":"/life/math/junior/grade-8/knowledge","kind":"知识讲解","scope":"general","audience":"general"},{"title":"八年级数学知识讲解 · 等腰三角形与垂直平分线至加权平均数与方差","link":"/life/math/junior/grade-8/knowledge-part-02","kind":"知识讲解","scope":"general","audience":"general"},{"title":"八年级数学知识讲解 · 平方根、立方根与实数至三角形全等与对应关系","link":"/life/math/junior/grade-8/knowledge-part-01","kind":"知识讲解","scope":"general","audience":"general"},{"title":"程序员数学 01：从编程问题选择学习路线","link":"/life/math/programmer/overview","kind":"知识讲解","scope":"general","audience":"general"}],"prev":{"text":"小学四年级数学：独立习题集 · 大数、数级与十进制至多位小数加减与简算","link":"/life/math/primary/grade-4/exercises-part-01"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"小学四年级数学：独立习题集 · 大数、数级与十进制至多位小数加减与简算","link":"/life/math/primary/grade-4/exercises-part-01"},"next":false},"headers":[],"relativePath":"life/math/primary/grade-4/exercises-part-02.md","filePath":"life/math/primary/grade-4/exercises-part-02.md"}'),p={name:"life/math/primary/grade-4/exercises-part-02.md"};function o(l,a,i,n,d,m){return e(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="小学四年级数学-独立习题集-·-小数与单位换算至植树间隔与周期规律" tabindex="-1">小学四年级数学：独立习题集 · 小数与单位换算至植树间隔与周期规律 <a class="header-anchor" href="#小学四年级数学-独立习题集-·-小数与单位换算至植树间隔与周期规律" aria-label="Permalink to &quot;小学四年级数学：独立习题集 · 小数与单位换算至植树间隔与周期规律&quot;">​</a></h1><p><a href="/life/math/primary/grade-4/exercises">返回分篇目录</a></p><p><a href="/life/math/primary/grade-4/knowledge">知识讲解</a> · <a href="/life/math/primary/grade-4/formulas">公式速查</a> · <a href="/life/math/primary/grade-4/exercises">独立习题集</a></p><p>按六三三学段编排的通用建议学习顺序；不同地区、教材和学期安排存在差异。本版覆盖以下明确列出的知识点，不将其等同于所有教材或完整课程标准。</p><h2 id="p4-11" tabindex="-1">小数与单位换算 <a class="header-anchor" href="#p4-11" aria-label="Permalink to &quot;小数与单位换算 {#p4-11}&quot;">​</a></h2><p><a href="/life/math/primary/grade-4/knowledge#p4-11">复习讲解</a> · <a href="/life/math/primary/grade-4/formulas#p4-11">公式规则</a></p><h3 id="q21" tabindex="-1">题 21 <a class="header-anchor" href="#q21" aria-label="Permalink to &quot;题 21 {#q21}&quot;">​</a></h3><p>把 3 千克 45 克化成以千克为单位的小数。</p><p>知识点：p4-11 小数与单位换算。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 3.045 千克。</p><p><strong>推导步骤：</strong> 45 克＝45÷1000＝0.045 千克，再加 3 千克。</p><p><strong>易错提醒：</strong> 千克与克的进率是 1000。</p></details><h3 id="q22" tabindex="-1">题 22 <a class="header-anchor" href="#q22" aria-label="Permalink to &quot;题 22 {#q22}&quot;">​</a></h3><p>0.6 平方米等于多少平方厘米？</p><p>知识点：p4-11 小数与单位换算。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 6000 平方厘米。</p><p><strong>推导步骤：</strong> 1 平方米＝10000 平方厘米，0.6×10000＝6000。</p><p><strong>易错提醒：</strong> 不能按米与厘米的进率只乘 100。</p></details><h2 id="p4-12" tabindex="-1">量角、角的分类与角度关系 <a class="header-anchor" href="#p4-12" aria-label="Permalink to &quot;量角、角的分类与角度关系 {#p4-12}&quot;">​</a></h2><p><a href="/life/math/primary/grade-4/knowledge#p4-12">复习讲解</a> · <a href="/life/math/primary/grade-4/formulas#p4-12">公式规则</a></p><h3 id="q23" tabindex="-1">题 23 <a class="header-anchor" href="#q23" aria-label="Permalink to &quot;题 23 {#q23}&quot;">​</a></h3><p>一个平角分成两个角，其中一个为 47°，另一个是多少度、属于什么角？</p><p>知识点：p4-12 量角、角的分类与角度关系。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 133°，钝角。</p><p><strong>推导步骤：</strong> 180°−47°＝133°；133°大于 90°小于 180°。</p><p><strong>易错提醒：</strong> 两个角合成的是平角，应从 180°中减去 47°，而不是从 90°中减。</p></details><h3 id="q24" tabindex="-1">题 24 <a class="header-anchor" href="#q24" aria-label="Permalink to &quot;题 24 {#q24}&quot;">​</a></h3><p>一个周角中已划出 90°和 120°两个不重叠的角，剩余部分的角度总和是多少度？</p><p>知识点：p4-12 量角、角的分类与角度关系。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 150°。</p><p><strong>推导步骤：</strong> 整周为 360°，360°−90°−120°＝150°。</p><p><strong>易错提醒：</strong> 题目说明两个已划出的角不重叠，才能直接相减。</p></details><h2 id="p4-13" tabindex="-1">直线、射线、线段与平行垂直 <a class="header-anchor" href="#p4-13" aria-label="Permalink to &quot;直线、射线、线段与平行垂直 {#p4-13}&quot;">​</a></h2><p><a href="/life/math/primary/grade-4/knowledge#p4-13">复习讲解</a> · <a href="/life/math/primary/grade-4/formulas#p4-13">公式规则</a></p><h3 id="q25" tabindex="-1">题 25 <a class="header-anchor" href="#q25" aria-label="Permalink to &quot;题 25 {#q25}&quot;">​</a></h3><p>两条直线相交形成一个 90°的角，它们是什么关系？其余三个角是多少度？</p><p>知识点：p4-13 直线、射线、线段与平行垂直。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 互相垂直；其余三个角也各为 90°。</p><p><strong>推导步骤：</strong> 垂直定义要求直角；相邻角合成 180°，因此相邻角也为 90°，对面的角同理。</p><p><strong>易错提醒：</strong> 不是只有量到的那一个角才是直角。</p></details><h3 id="q26" tabindex="-1">题 26 <a class="header-anchor" href="#q26" aria-label="Permalink to &quot;题 26 {#q26}&quot;">​</a></h3><p>从路边一点 A 到一条笔直公路，画出一条垂直线段长 12 米和一条斜线段长 15 米。A 到公路的距离是多少？</p><p>知识点：p4-13 直线、射线、线段与平行垂直。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 12 米。</p><p><strong>推导步骤：</strong> 点到直线距离按垂直线段定义，且它是最短的连接线段。</p><p><strong>易错提醒：</strong> 不能把任意连接公路的斜线段长度当作距离。</p></details><h2 id="p4-14" tabindex="-1">三角形分类、三边关系与内角和 <a class="header-anchor" href="#p4-14" aria-label="Permalink to &quot;三角形分类、三边关系与内角和 {#p4-14}&quot;">​</a></h2><p><a href="/life/math/primary/grade-4/knowledge#p4-14">复习讲解</a> · <a href="/life/math/primary/grade-4/formulas#p4-14">公式规则</a></p><h3 id="q27" tabindex="-1">题 27 <a class="header-anchor" href="#q27" aria-label="Permalink to &quot;题 27 {#q27}&quot;">​</a></h3><p>长 4 厘米、6 厘米、9 厘米的三根小棒能围成三角形吗？</p><p>知识点：p4-14 三角形分类、三边关系与内角和。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 能。</p><p><strong>推导步骤：</strong> 最长为 9，较短两边和 4＋6＝10＞9；其余两组不等式自然成立。</p><p><strong>易错提醒：</strong> “大于”不能改成“大于或等于”。</p></details><h3 id="q28" tabindex="-1">题 28 <a class="header-anchor" href="#q28" aria-label="Permalink to &quot;题 28 {#q28}&quot;">​</a></h3><p>等腰三角形顶角为 36°，两个底角各是多少度？</p><p>知识点：p4-14 三角形分类、三边关系与内角和。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 各 72°。</p><p><strong>推导步骤：</strong> 两个底角的和是 180°−36°＝144°，等腰底角相等，144°÷2＝72°。</p><p><strong>易错提醒：</strong> 不能把 144°直接作为一个底角。</p></details><h2 id="p4-15" tabindex="-1">平行四边形、梯形与高 <a class="header-anchor" href="#p4-15" aria-label="Permalink to &quot;平行四边形、梯形与高 {#p4-15}&quot;">​</a></h2><p><a href="/life/math/primary/grade-4/knowledge#p4-15">复习讲解</a> · <a href="/life/math/primary/grade-4/formulas#p4-15">公式规则</a></p><h3 id="q29" tabindex="-1">题 29 <a class="header-anchor" href="#q29" aria-label="Permalink to &quot;题 29 {#q29}&quot;">​</a></h3><p>一个四边形两组对边分别平行，四个角都是直角，它既属于哪两类常见四边形？</p><p>知识点：p4-15 平行四边形、梯形与高。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 长方形和平行四边形；若四边还相等，则也属于正方形。</p><p><strong>推导步骤：</strong> 直角条件确定长方形；两组对边平行符合平行四边形定义。</p><p><strong>易错提醒：</strong> 分类可以包含，不能认为每个图形只能属于一种大类。</p></details><h3 id="q30" tabindex="-1">题 30 <a class="header-anchor" href="#q30" aria-label="Permalink to &quot;题 30 {#q30}&quot;">​</a></h3><p>一个梯形两条平行底边之间的垂直距离为 4 厘米，斜腰长 5 厘米。它以这两条平行边为底时，高是多少？</p><p>知识点：p4-15 平行四边形、梯形与高。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 4 厘米。</p><p><strong>推导步骤：</strong> 高按垂直距离确定，题目已经给出垂直距离为 4 厘米。</p><p><strong>易错提醒：</strong> 腰不一定垂直于底，不能把腰长直接当高。</p></details><h2 id="p4-16" tabindex="-1">数对、方格位置与平移 <a class="header-anchor" href="#p4-16" aria-label="Permalink to &quot;数对、方格位置与平移 {#p4-16}&quot;">​</a></h2><p><a href="/life/math/primary/grade-4/knowledge#p4-16">复习讲解</a> · <a href="/life/math/primary/grade-4/formulas#p4-16">公式规则</a></p><h3 id="q31" tabindex="-1">题 31 <a class="header-anchor" href="#q31" aria-label="Permalink to &quot;题 31 {#q31}&quot;">​</a></h3><p>方格图列向右、行向上增加。点 A 的数对为 (3,2)，向右移 2 格，再向上移 4 格，终点数对是多少？</p><p>知识点：p4-16 数对、方格位置与平移。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> (5,6)。</p><p><strong>推导步骤：</strong> 列号 3＋2＝5，行号 2＋4＝6，两次位移分别影响一个坐标。</p><p><strong>易错提醒：</strong> 不要把行、列变化颠倒。</p></details><h3 id="q32" tabindex="-1">题 32 <a class="header-anchor" href="#q32" aria-label="Permalink to &quot;题 32 {#q32}&quot;">​</a></h3><p>方格图中 B 在第 6 列第 4 行，C 在第 2 列第 4 行。从 B 到 C 沿横向应怎样移动？</p><p>知识点：p4-16 数对、方格位置与平移。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 向左移动 4 格。</p><p><strong>推导步骤：</strong> 行号相同，列号由 6 减到 2，减少 4，所以左移 4 格。</p><p><strong>易错提醒：</strong> 位置差为 4 个间隔，不能数成 5 个点。</p></details><h2 id="p4-17" tabindex="-1">平均数与移多补少 <a class="header-anchor" href="#p4-17" aria-label="Permalink to &quot;平均数与移多补少 {#p4-17}&quot;">​</a></h2><p><a href="/life/math/primary/grade-4/knowledge#p4-17">复习讲解</a> · <a href="/life/math/primary/grade-4/formulas#p4-17">公式规则</a></p><h3 id="q33" tabindex="-1">题 33 <a class="header-anchor" href="#q33" aria-label="Permalink to &quot;题 33 {#q33}&quot;">​</a></h3><p>四天分别用水 18、22、19、21 桶，平均每天用多少桶？</p><p>知识点：p4-17 平均数与移多补少。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 20 桶。</p><p><strong>推导步骤：</strong> 总量为 18＋22＋19＋21＝80 桶，80÷4＝20 桶。</p><p><strong>易错提醒：</strong> 数据共有四个，除数是 4。</p></details><h3 id="q34" tabindex="-1">题 34 <a class="header-anchor" href="#q34" aria-label="Permalink to &quot;题 34 {#q34}&quot;">​</a></h3><p>3 人平均跳绳 90 下，另 2 人平均跳绳 100 下，5 人平均跳多少下？</p><p>知识点：p4-17 平均数与移多补少。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 94 下。</p><p><strong>推导步骤：</strong> 总次数为 3×90＋2×100＝470，470÷5＝94。</p><p><strong>易错提醒：</strong> 不能直接算 (90＋100)÷2，因为两组人数不同。</p></details><h2 id="p4-18" tabindex="-1">条形统计图与刻度 <a class="header-anchor" href="#p4-18" aria-label="Permalink to &quot;条形统计图与刻度 {#p4-18}&quot;">​</a></h2><p><a href="/life/math/primary/grade-4/knowledge#p4-18">复习讲解</a> · <a href="/life/math/primary/grade-4/formulas#p4-18">公式规则</a></p><h3 id="q35" tabindex="-1">题 35 <a class="header-anchor" href="#q35" aria-label="Permalink to &quot;题 35 {#q35}&quot;">​</a></h3><p>某条形图每格表示 4 本书，故事书条高 7 格，科普书条高 5 格。故事书比科普书多多少本？</p><p>知识点：p4-18 条形统计图与刻度。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 8 本。</p><p><strong>推导步骤：</strong> 条高相差 2 格，2×4＝8 本；或分别算 28−20。</p><p><strong>易错提醒：</strong> 两格不是两本。</p></details><h3 id="q36" tabindex="-1">题 36 <a class="header-anchor" href="#q36" aria-label="Permalink to &quot;题 36 {#q36}&quot;">​</a></h3><p>绘制人数分别为 12、18、24 的条形图，每格代表 3 人，各条应画几格？</p><p>知识点：p4-18 条形统计图与刻度。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 分别为 4、6、8 格。</p><p><strong>推导步骤：</strong> 依次计算 12÷3、18÷3、24÷3。</p><p><strong>易错提醒：</strong> 一张图应保持同一刻度，不能分别改变每格人数。</p></details><h2 id="p4-19" tabindex="-1">统筹安排与最优顺序 <a class="header-anchor" href="#p4-19" aria-label="Permalink to &quot;统筹安排与最优顺序 {#p4-19}&quot;">​</a></h2><p><a href="/life/math/primary/grade-4/knowledge#p4-19">复习讲解</a> · <a href="/life/math/primary/grade-4/formulas#p4-19">公式规则</a></p><h3 id="q37" tabindex="-1">题 37 <a class="header-anchor" href="#q37" aria-label="Permalink to &quot;题 37 {#q37}&quot;">​</a></h3><p>电热水壶烧水需 10 分钟，烧水时可洗杯子 4 分钟并接着摆茶具 3 分钟，水开后泡茶需 2 分钟。最少几分钟完成？</p><p>知识点：p4-19 统筹安排与最优顺序。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 12 分钟。</p><p><strong>推导步骤：</strong> 洗杯和摆茶具共 7 分钟，可在烧水的 10 分钟内完成；水开后再泡茶 2 分钟，总计 12。</p><p><strong>易错提醒：</strong> 泡茶依赖水烧开，不能放到前面同时完成。</p></details><h3 id="q38" tabindex="-1">题 38 <a class="header-anchor" href="#q38" aria-label="Permalink to &quot;题 38 {#q38}&quot;">​</a></h3><p>三人办理业务分别需要 2、5、8 分钟，只能一次办理一人。让三人的“从开始排队到办完”时间之和最小，应按什么顺序？总和多少分钟？</p><p>知识点：p4-19 统筹安排与最优顺序。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 按 2、5、8 分钟的顺序；总和 24 分钟。</p><p><strong>推导步骤：</strong> 依次完成时刻为 2、7、15，合计 24；短业务先做可减少后面所有人的等待。</p><p><strong>易错提醒：</strong> 题目求完成时间总和，不是最后一人办完的 15 分钟。</p></details><h2 id="p4-20" tabindex="-1">植树间隔与周期规律 <a class="header-anchor" href="#p4-20" aria-label="Permalink to &quot;植树间隔与周期规律 {#p4-20}&quot;">​</a></h2><p><a href="/life/math/primary/grade-4/knowledge#p4-20">复习讲解</a> · <a href="/life/math/primary/grade-4/formulas#p4-20">公式规则</a></p><h3 id="q39" tabindex="-1">题 39 <a class="header-anchor" href="#q39" aria-label="Permalink to &quot;题 39 {#q39}&quot;">​</a></h3><p>长 100 米的直路一侧，每 10 米种一棵树，两端都种，需要多少棵？</p><p>知识点：p4-20 植树间隔与周期规律。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 11 棵。</p><p><strong>推导步骤：</strong> 间隔数 100÷10＝10，直线两端都种要比间隔数多 1 棵，共 11 棵。</p><p><strong>易错提醒：</strong> 不能把 10 个间隔直接当作 10 棵树。</p></details><h3 id="q40" tabindex="-1">题 40 <a class="header-anchor" href="#q40" aria-label="Permalink to &quot;题 40 {#q40}&quot;">​</a></h3><p>彩旗按红、黄、蓝、绿四面循环排列，第 30 面是什么颜色？</p><p>知识点：p4-20 植树间隔与周期规律。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 黄色。</p><p><strong>推导步骤：</strong> 30÷4＝7……2，前 28 面构成 7 个完整周期，第 30 面是新周期第 2 面。</p><p><strong>易错提醒：</strong> 余数为 0 时应取周期最后一项，本题余数为 2。</p></details>',104)])])}const c=r(p,[["render",o]]);export{g as __pageData,c as default};
